import os,glob,re,json
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]

def comps(g,val):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==val and (i,j) not in seen:
                st=[(i,j)]; c=[]
                while st:
                    y,x=st.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x)); c.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            yy,xx=y+dy,x+dx
                            if 0<=yy<H and 0<=xx<W and g[yy][xx]==val and (yy,xx) not in seen:
                                st.append((yy,xx))
                out.append(c)
    return out

def norm(c):
    ys=[p[0] for p in c]; xs=[p[1] for p in c]
    y0,x0=min(ys),min(xs)
    s={(y-y0,x-x0) for y,x in c}
    h=max(y for y,x in s)+1; w=max(x for y,x in s)+1
    return tuple(tuple(1 if (y,x) in s else 0 for x in range(w)) for y in range(h))

